"use strict";
// Regenerates data/*.js from the raw keybr.com files in data/raw/.
// Usage: node tools/build-data.js
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const HEADER =
  "// Generated by tools/build-data.js — do not edit by hand.\n" +
  "// Data from keybr.com (https://github.com/aradzie/keybr.com),\n" +
  "// Copyright (c) Aleksei Radzievskii, licensed under AGPL-3.0.\n";

function write(name, key, value) {
  const out =
    HEADER +
    "(globalThis.LTT_DATA = globalThis.LTT_DATA || {})." + key + " = " +
    JSON.stringify(value) + ";\n";
  fs.writeFileSync(path.join(ROOT, "data", name), out);
  console.log("wrote data/" + name);
}

const raw = (f) => fs.readFileSync(path.join(ROOT, "data/raw", f));

write("model-en.js", "modelEnBase64", raw("model-en.data").toString("base64"));
write("words-en.js", "wordsEn",
  JSON.parse(raw("words-en.json")).filter((w) => /^[a-z]+$/.test(w)));
write("blacklist-en.js", "blacklistEnScrambled", JSON.parse(raw("blacklist-en.json")));
